#!/usr/bin/env python3
"""Generate the Gazebo world and the matching Nav2 map from config/arena.yaml.

Usage:  python3 scripts/generate_arena.py   (run from the mrc_gazebo package dir)
"""
import math
import os
import sys

import numpy as np
import yaml

PKG = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

WORLD_HEADER = """<?xml version="1.0"?>
<!-- GENERATED by scripts/generate_arena.py from config/arena.yaml - do not edit by hand -->
<sdf version="1.9">
  <world name="{name}">
    <physics name="2ms" type="ignored">
      <max_step_size>0.002</max_step_size>
      <real_time_factor>1.0</real_time_factor>
    </physics>
    <plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics"/>
    <plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands"/>
    <plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster"/>
    <plugin filename="gz-sim-sensors-system" name="gz::sim::systems::Sensors">
      <render_engine>ogre2</render_engine>
    </plugin>
    <plugin filename="gz-sim-imu-system" name="gz::sim::systems::Imu"/>
    <scene>
      <ambient>0.6 0.6 0.6 1</ambient>
      <background>0.75 0.8 0.85 1</background>
      <shadows>false</shadows>
      <grid>false</grid>
    </scene>
    <light name="sun" type="directional">
      <cast_shadows>false</cast_shadows>
      <pose>0 0 10 0 0 0</pose>
      <diffuse>0.9 0.9 0.9 1</diffuse>
      <specular>0.2 0.2 0.2 1</specular>
      <direction>-0.3 0.2 -0.9</direction>
    </light>
    <model name="ground_plane">
      <static>true</static>
      <link name="link">
        <collision name="collision">
          <geometry><plane><normal>0 0 1</normal><size>60 60</size></plane></geometry>
        </collision>
        <visual name="visual">
          <geometry><plane><normal>0 0 1</normal><size>60 60</size></plane></geometry>
          <material><ambient>0.85 0.85 0.82 1</ambient><diffuse>0.85 0.85 0.82 1</diffuse></material>
        </visual>
      </link>
    </model>
"""

BOX = """    <model name="{name}">
      <static>true</static>
      <pose>{x:.3f} {y:.3f} {z:.3f} 0 0 0</pose>
      <link name="link">
        <collision name="collision"><geometry><box><size>{sx:.3f} {sy:.3f} {h:.3f}</size></box></geometry></collision>
        <visual name="visual"><geometry><box><size>{sx:.3f} {sy:.3f} {h:.3f}</size></box></geometry>
          <material><ambient>{c}</ambient><diffuse>{c}</diffuse></material></visual>
      </link>
    </model>
"""

CYL = """    <model name="{name}">
      <static>true</static>
      <pose>{x:.3f} {y:.3f} {z:.3f} 0 0 0</pose>
      <link name="link">
        <collision name="collision"><geometry><cylinder><radius>{r:.3f}</radius><length>{h:.3f}</length></cylinder></geometry></collision>
        <visual name="visual"><geometry><cylinder><radius>{r:.3f}</radius><length>{h:.3f}</length></cylinder></geometry>
          <material><ambient>{c}</ambient><diffuse>{c}</diffuse></material></visual>
      </link>
    </model>
"""

def main():
    cfg = yaml.safe_load(open(os.path.join(PKG, 'config', 'arena.yaml')))
    name = cfg['name']
    i = cfg['interior']
    t, wh = cfg['wall']['thickness'], cfg['wall']['height']

    # Outer walls expressed as boxes so the world and the map share one code path.
    cx, cy = (i['x_min'] + i['x_max']) / 2, (i['y_min'] + i['y_max']) / 2
    lx, ly = i['x_max'] - i['x_min'] + 2 * t, i['y_max'] - i['y_min'] + 2 * t
    walls = [
        ['wall_north', cx, i['y_max'] + t / 2, lx, t, wh],
        ['wall_south', cx, i['y_min'] - t / 2, lx, t, wh],
        ['wall_east', i['x_max'] + t / 2, cy, t, ly, wh],
        ['wall_west', i['x_min'] - t / 2, cy, t, ly, wh],
    ]
    boxes = walls + cfg.get('boxes', [])
    cyls = cfg.get('cylinders', [])

    # ---------------- world ----------------
    out = [WORLD_HEADER.format(name=name)]
    for b in boxes:
        col = '0.55 0.55 0.6 1' if b[0].startswith('wall') else '0.75 0.45 0.2 1'
        out.append(BOX.format(name=b[0], x=b[1], y=b[2], z=b[5] / 2, sx=b[3], sy=b[4], h=b[5], c=col))
    for c in cyls:
        out.append(CYL.format(name=c[0], x=c[1], y=c[2], z=c[4] / 2, r=c[3], h=c[4], c='0.2 0.45 0.7 1'))
    out.append('  </world>\n</sdf>\n')
    world_path = os.path.join(PKG, 'worlds', f'{name}.sdf')
    open(world_path, 'w').write(''.join(out))

    # ---------------- map ----------------
    res, margin = cfg['map']['resolution'], cfg['map']['margin']
    ox, oy = i['x_min'] - t - margin, i['y_min'] - t - margin
    w = int(round((i['x_max'] - i['x_min'] + 2 * (t + margin)) / res))
    h = int(round((i['y_max'] - i['y_min'] + 2 * (t + margin)) / res))
    # cell centres in world coordinates
    xs = ox + (np.arange(w) + 0.5) * res
    ys = oy + (np.arange(h) + 0.5) * res
    X, Y = np.meshgrid(xs, ys)          # row 0 = lowest y
    grid = np.full((h, w), 205, np.uint8)   # unknown outside the arena
    inside = (X >= i['x_min'] - t) & (X <= i['x_max'] + t) & (Y >= i['y_min'] - t) & (Y <= i['y_max'] + t)
    grid[inside] = 254                  # free
    occ = np.zeros_like(inside)
    for b in boxes:
        occ |= (np.abs(X - b[1]) <= b[3] / 2) & (np.abs(Y - b[2]) <= b[4] / 2)
    for c in cyls:
        occ |= (X - c[1]) ** 2 + (Y - c[2]) ** 2 <= c[3] ** 2
    grid[occ] = 0
    pgm = np.flipud(grid)               # PGM row 0 is the top (highest y)
    map_base = os.path.join(PKG, 'maps', name)
    with open(map_base + '.pgm', 'wb') as f:
        f.write(f'P5\n# generated by generate_arena.py\n{w} {h}\n255\n'.encode())
        f.write(pgm.tobytes())
    with open(map_base + '.yaml', 'w') as f:
        yaml.safe_dump({'image': f'{name}.pgm', 'mode': 'trinary', 'resolution': res,
                        'origin': [round(ox, 4), round(oy, 4), 0.0], 'negate': 0,
                        'occupied_thresh': 0.65,
                        # 0.196 (not 0.25!) so that pixel 205 loads as UNKNOWN
                        'free_thresh': 0.196}, f, sort_keys=False)
    print(f'world -> {world_path}\nmap   -> {map_base}.pgm/.yaml ({w}x{h} @ {res} m)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
